const state={summary:null,wells:[],allWells:[],curves:[],interpretations:[],interpretationWorkbench:null,core:null,timeDepth:[],seismic:[],production:null,modelInventory:null,modelTypeFilter:'',horizonWorkbench:null,horizonDetail:null,horizonSelectedWells:new Set(),horizonTrajectories:[],relationshipMode:'single',relationshipHistMode:'ratio',polygons:[],sources:[],mapPoints:[],activePage:'overview',catalog:null,catalogCategory:'',catalogPage:1,wellView:'table'};
const pageInfo={database:['资料数据库','查看完整目录索引、解析状态、原始路径与人工归类'],overview:['数据总览','摸清工区数据家底，追溯每一个统计数字'],import:['导入数据','建立统一、可追溯的地质数据目录'],wells:['井与井名','统一查找、二维分布、来源联动和疑似同井核对'],core:['岩心标定','关联岩心照片、深度段与 DEV 井轨迹'],curves:['测井曲线','统计物理测井曲线覆盖井数、深度与有效样点'],interpretations:['解释结论','统一孔隙度、渗透率、饱和度与岩相等解释类型'],['time-depth']:['时深关系','独立统计 OWT、TWT 与井震标定关系'],horizons:['层位指定','统计 Well Top 方案、构造面版本与 DEV 轨迹钻遇关系'],seismic:['地震工区','扫描 SEG-Y 道头，判断维度与空间范围'],production:['生产动态','梳理投产、月度产量、开关井、累产、压力与射孔层段'],['production-clustering']:['生产聚类','融合生产时序、层位、射孔、措施与空间邻井，形成可解释的井产能分型'],models:['模型数据','统计地质模型、油藏模型、配套图件、拟合与预测方案'],reserves:['储量计算','按构造面和属性平面组织多套参数组，计算并圈定统计油气储量'],map:['空间圈选','框选、缩放并按可见 Polygon 图层筛选井'],['format-conversion']:['格式转化','将工区导出文件规整为可交付的标准字段表，源文件保持只读'],['directory-translation']:['目录翻译','为外语文件名建立软件内中文显示别名，不改写本地源文件'],['data-export']:['导出数据','按曲线类型交付原始 LAS，并按统一井名去重交付有效 DEV 轨迹']};
const typeLabels={well_head:'Well Head',well_heads:'Well Head',deviation:'井斜轨迹',well_paths:'井斜轨迹',las:'LAS 测井',well_logs:'LAS 测井',checkshot:'Checkshot',checkshots:'Checkshot',well_top:'井顶',well_tops:'井顶',interpretation:'解释结论',interpretations:'解释结论',core:'岩心标定',seismic:'SEG-Y',seismic_3d:'3D 地震',seismic_2d:'2D 地震',horizons:'层位',faults:'断层',polygon:'Polygon',polygons:'Polygon',production:'生产数据',other:'其他资料',alias:'井名别名'};
const fmt=(v,d=0)=>v===null||v===undefined||v===''?'—':Number(v).toLocaleString('zh-CN',{maximumFractionDigits:d});
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
async function api(url,options){const response=await fetch(url,options);let data={};try{data=await response.json()}catch{}if(!response.ok)throw new Error(data.error||`请求失败 ${response.status}`);return data}
function toast(message,error=false){const el=document.querySelector('#toast');el.textContent=message;el.className=`toast show${error?' error':''}`;clearTimeout(el._timer);el._timer=setTimeout(()=>el.className='toast',3200)}
function tags(values){return (values||[]).map(v=>`<span class="tag">${esc(typeLabels[v]||v)}</span>`).join('')||'—'}
function quality(row){const status=row.identity_status||row.quality_label||'待核实身份',cls=status==='多源互证'?'high':status==='单源硬证据'?'medium':'low';return `<span class="quality" title="${esc(row.verification_reason||'')}"><i class="dot ${cls}"></i><span>${esc(status)}</span></span>`}
function optionFields(){return `<label>数据类型<select name="data_type"><option value="auto">自动识别</option><option value="well_head">Well Head Excel / CSV</option><option value="deviation">Well Dev / 井斜</option><option value="las">Well LAS</option><option value="interpretation">解释结论</option><option value="core">岩心数据</option><option value="production">生产动态 / 射孔层段</option><option value="seismic">Seismic SEG-Y</option><option value="polygon">Polygon</option><option value="alias">井名别名表</option></select></label><label>批次<input name="batch" placeholder="如 2026-Q3"></label><label>版本<input name="version" placeholder="如 Petrel_v2"></label><label>坐标系<input name="crs" placeholder="如 EPSG:32648"></label>`}
document.querySelectorAll('.options-fields').forEach(el=>el.innerHTML=optionFields());

async function loadOverview(){const [summary,sources]=await Promise.all([api('/api/summary'),api('/api/sources')]);state.summary=summary;state.sources=sources;const metrics=[['⌖',summary.wells,'统一井数','wells'],['◎',summary.located_wells,'有坐标井','located'],['〽',summary.curve_types,'测井曲线类型','curves'],['▤',summary.interpretation_types,'解释 / 岩心属性','interpretations'],['≋',summary.seismic_surveys,'地震工区','seismic'],['◇',summary.polygons,'Polygon','polygons']];document.querySelector('#summary-metrics').innerHTML=metrics.map(m=>`<button type="button" class="metric overview-metric" data-overview-metric="${m[3]}" title="查看${m[2]}明细"><span class="metric-icon">${m[0]}</span><strong>${fmt(m[1])}</strong><span>${m[2]}</span><em>查看明细 →</em></button>`).join('');if(typeof bindOverviewMetricCards==='function')bindOverviewMetricCards();renderSourceScopes(summary);renderConfidence(summary.confidence,summary.wells,summary.identity_standard);document.querySelector('#recent-sources').innerHTML=sources.slice(0,8).map(s=>`<tr><td title="${esc(s.file_path)}">${esc(s.filename)}</td><td>${esc(typeLabels[s.data_type]||s.data_type)}</td><td>${esc([s.batch,s.version].filter(Boolean).join(' / ')||'—')}</td><td>${fmt(s.record_count)}</td><td><span class="status ${s.status}">${s.status==='ready'?'完成':s.status==='failed'?'失败':'处理中'}</span></td><td>${esc((s.imported_at||'').replace('T',' ').slice(0,19))}</td></tr>`).join('')||`<tr><td colspan="6" class="empty-state">尚未导入数据</td></tr>`}
function sourceRowNote(row){if(row.data_type==='checkshots'&&row.duplicate_groups?.length){const duplicates=row.duplicate_groups.map(group=>`${group.well_key}: ${group.files.join(' + ')}`).join('；');return `${row.explanation} ${duplicates}`}if(row.scope==='representative')return `${row.explanation}${row.representative_file?` 代表文件：${row.representative_file}，识别 ${fmt(row.representative_unique_wells)} 口。`:''}`;return row.explanation||''}
function renderSourceScopes(summary){const well=summary.well_source_coverage,file=summary.file_source_composition;if(!well||!file){renderLegacySourceScope(summary.source_breakdown||[]);return}document.querySelector('#well-source-denominator').textContent=`分母：${well.denominator_label} ${fmt(well.denominator)} 口${well.filter_active?'（已应用井点筛选）':''}`;const wellEl=document.querySelector('#well-source-bars');wellEl.className='scope-bars';wellEl.innerHTML=well.rows.map(row=>{const estimate=row.scope==='representative',missing=estimate?'代表样本，不计算全量缺口':`缺 ${fmt(row.missing_wells)} 口`,files=row.data_type==='well_heads'&&row.raw_records?`${fmt(row.raw_records)} 条原始记录 · ${fmt(row.snapshot_files)} 个扫描文件`:`${fmt(row.primary_files)} 主数据${row.supporting_files?` + ${fmt(row.supporting_files)} 附属`:''}`;return `<div class="scope-row ${estimate?'estimate':''}"><header><span><b>${esc(row.label)}</b><em>${esc(row.description)}</em></span><strong>${fmt(row.well_count)} / ${fmt(row.denominator)} 口</strong></header><div class="scope-track"><i style="width:${Math.min(100,row.coverage_percentage)}%"></i></div><footer><b>${fmt(row.coverage_percentage,2)}%</b><span>${esc(missing)} · ${esc(files)}</span></footer><p>${esc(sourceRowNote(row))}</p></div>`}).join('');document.querySelector('#file-source-denominator').textContent=`分母：${file.denominator_label} ${fmt(file.denominator)} 个；井类资料不在此重复计算覆盖率`;const fileEl=document.querySelector('#file-source-bars');fileEl.className='file-scope-bars';fileEl.innerHTML=file.rows.map(row=>{const components=row.components.length>1?row.components.map(item=>`${item.label} ${fmt(item.files)}`).join(' + '):'',parts=`${fmt(row.primary_files)} 主数据${row.supporting_files?` + ${fmt(row.supporting_files)} 附属/组件`:''}`;return `<div class="file-scope-row"><span><b>${esc(row.label)}</b><em>${esc(components||parts)}</em></span><div class="scope-track"><i style="width:${Math.min(100,row.percentage)}%"></i></div><strong>${fmt(row.files)} / ${fmt(row.denominator)}<small>${fmt(row.percentage,3)}%</small></strong><p>${esc(parts)}</p></div>`}).join('')}
function renderLegacySourceScope(rows){const wellEl=document.querySelector('#well-source-bars'),fileEl=document.querySelector('#file-source-bars');wellEl.className='scope-bars empty-state';wellEl.textContent='当前导入库尚未建立统一的井类覆盖口径';fileEl.className='file-scope-bars';const total=rows.reduce((sum,row)=>sum+row.files,0);fileEl.innerHTML=rows.map(row=>`<div class="file-scope-row"><span><b>${esc(typeLabels[row.data_type]||row.data_type)}</b></span><div class="scope-track"><i style="width:${total?row.files/total*100:0}%"></i></div><strong>${fmt(row.files)} / ${fmt(total)}<small>${total?fmt(row.files/total*100,2):0}%</small></strong></div>`).join('')}
function renderConfidence(rows,total,standard={}){const el=document.querySelector('#confidence-chart');if(!rows.length){el.className='donut-wrap empty-state';el.textContent='暂无数据';return}const map=Object.fromEntries(rows.map(r=>[r.level,r.count])),verified=map['多源互证']||0,single=map['单源硬证据']||0,pending=map['待核实身份']||0,vp=total?verified/total*100:0,sp=total?single/total*100:0;el.className='donut-wrap';el.innerHTML=`<div class="donut" style="background:conic-gradient(#2b9d6a 0 ${vp}%,#43a8b1 ${vp}% ${vp+sp}%,#c45a50 ${vp+sp}% 100%)"><b>${fmt(total)}</b></div><div class="donut-legend"><span><em><i style="background:#2b9d6a"></i>多源互证</em><b>${verified}</b></span><span><em><i style="background:#43a8b1"></i>单源硬证据</em><b>${single}</b></span><span><em><i style="background:#c45a50"></i>待核实身份</em><b>${pending}</b></span></div>`;document.querySelector('#identity-standard').innerHTML=`<p><b>井实体：</b>${esc(standard.existence||'Well Head、DEV、LAS 任一出现即确认存在')}</p><p><b>待核实：</b>${esc(standard.pending||'仅有辅助记录，或存在明确坐标冲突')}</p>`}

async function loadWells(){state.allWells=await api('/api/wells');state.wells=state.allWells;renderWells()}
function renderWells(){const q=document.querySelector('#well-search').value.trim().toUpperCase();const rows=state.wells.filter(w=>!q||[w.canonical_name,w.uwi,w.preferred_filename,...w.source_types].some(v=>String(v||'').toUpperCase().includes(q)));state.filteredWells=rows;document.querySelector('#well-count-label').textContent=`共 ${rows.length} 口统一井；点击“详情”查看所有原始来源`;document.querySelector('#wells-body').innerHTML=rows.map(w=>`<tr><td><strong>${esc(w.canonical_name)}</strong></td><td>${esc(w.uwi||'—')}</td><td>${tags(w.source_types)}</td><td>${fmt(w.curve_count)} 种</td><td>${w.log_start_md==null?(w.max_survey_md==null?'—':`DEV 0 – ${fmt(w.max_survey_md,2)}`):`${fmt(w.log_start_md,2)} – ${fmt(w.log_stop_md,2)}`}</td><td><span class="tag">${esc(typeLabels[w.preferred_type]||w.preferred_type||'—')}</span></td><td>${quality(w)}</td><td><button class="link-button" data-detail="${esc(w.id)}">详情</button></td></tr>`).join('')||`<tr><td colspan="8" class="empty-state">没有匹配的井</td></tr>`;document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>showWell(b.dataset.detail));if(state.wellView==='map')requestAnimationFrame(drawWellDistribution)}
async function showWell(id){
  const data=await api(`/api/wells/${encodeURIComponent(id)}`),w=data.well,dialog=document.querySelector('#well-dialog');
  const identity=`${esc(w.existence_label||'井实体已确认')} · ${esc(w.identity_status||w.quality_label||'待核实身份')} · ${esc(w.verification_reason||'')}`;
  const inline=state.activePage==='wells',target=document.querySelector(inline?'#well-inline-detail':'#well-detail');
  target.innerHTML=`<div class="detail-head"><h2>${esc(w.canonical_name)}</h2><p class="muted">${identity}${data.sampling_note?' · '+esc(data.sampling_note):''}</p></div><div class="detail-grid"><div class="detail-metric"><span>井口坐标</span><b>${w.x==null?'—':`${fmt(w.x,2)}, ${fmt(w.y,2)}`}</b></div><div class="detail-metric"><span>坐标系</span><b>${esc(w.crs||'未标注')}</b></div><div class="detail-metric"><span>KB 海拔</span><b>${fmt(w.kb_elevation,2)}</b></div><div class="detail-metric"><span>总井深 / DEV</span><b>${fmt(w.total_depth??w.max_survey_md,2)}</b></div></div>${data.coordinate_spread!=null?`<p class="${data.coordinate_spread>5?'warning-text':'muted'}">不同来源井位最大偏差：${fmt(data.coordinate_spread,2)}（坐标单位）</p>`:''}<div class="detail-section"><h3>原始来源证据（${data.sources.length}）</h3><div class="table-wrap"><table><thead><tr><th>原始井名</th><th>来源</th><th>文件</th><th>目录 / 版本</th><th>坐标</th></tr></thead><tbody>${data.sources.slice(0,150).map(s=>`<tr><td>${esc(s.raw_name)}</td><td>${esc(typeLabels[s.data_type]||s.data_type)}</td><td title="${esc(s.file_path||'')}">${s.catalog_id?`<button class="catalog-file-link" data-catalog-reveal="${s.catalog_id}">${esc(s.filename)}</button>`:esc(s.filename)}</td><td>${esc([s.batch,s.version].filter(Boolean).join(' / ')||'—')}</td><td>${s.x==null?'—':`${fmt(s.x,2)}, ${fmt(s.y,2)}`}</td></tr>`).join('')}</tbody></table></div></div><div class="detail-section"><h3>测井曲线（${data.curves.length} 条曲线记录）</h3><div>${data.curves.slice(0,100).map(c=>`<span class="tag" title="${esc(c.filename)} ${fmt(c.start_md,2)}–${fmt(c.stop_md,2)}">${esc(c.mnemonic)}${c.unit?' · '+esc(c.unit):''}</span>`).join('')||'<span class="muted">目录中有关联 LAS，曲线头段画像可在测井曲线界面查看</span>'}</div></div><div class="detail-section"><h3>关联轨迹文件</h3><div>${(data.dev_paths||[]).slice(0,20).map(path=>`<span class="tag" title="${esc(path)}">${esc(path.split(/[/\\]/).pop())}</span>`).join('')||'<span class="muted">无 DEV</span>'}</div></div><div class="detail-section"><h3>解释 / 岩心属性</h3><div>${data.interpretations.map(i=>`<span class="tag">${esc(i.attribute_name)} · ${i.values_count}</span>`).join('')||'<span class="muted">无已解析解释或岩心数据</span>'}</div></div>`;
  target.querySelectorAll('[data-catalog-reveal]').forEach(button=>button.onclick=()=>window.revealCatalogItem?.(button.dataset.catalogReveal,button.dataset.catalogRevealMode||'select',button));
  if(inline){document.querySelector('#well-inline-detail-panel').classList.remove('hidden');document.querySelectorAll('#wells-body tr').forEach(row=>row.classList.toggle('selected',row.querySelector(`[data-detail="${CSS.escape(id)}"]`)));state.selectedWellId=id}else dialog.showModal();
}

async function loadCurves(){state.curveWorkbench=await api('/api/curve-workbench');state.curves=state.curveWorkbench.curves||[];if(typeof invalidateTreeCards==='function')invalidateTreeCards();renderCurves();if(typeof renderCurveWorkbench==='function')renderCurveWorkbench()}
function renderCurves(){const q=document.querySelector('#curve-search').value.trim().toUpperCase();const rows=state.curves.filter(r=>r.mnemonic.includes(q));const max=Math.max(1,...rows.map(r=>r.well_count));document.querySelector('#curve-bars').innerHTML=rows.slice(0,15).map(r=>`<button type="button" class="bar-row curve-coverage-row" data-curve-detail="${esc(r.mnemonic)}" data-curve-detail-view="wells" title="查看 ${esc(r.mnemonic)} 的 ${fmt(r.well_count)} 口井"><b title="${esc(r.mnemonic)}">${esc(r.mnemonic)}</b><div class="bar-track"><div class="bar-fill" style="width:${r.well_count/max*100}%"></div></div><span>${r.well_count} 口井</span></button>`).join('')||'<div class="empty-state">尚未发现代表 LAS 曲线</div>';document.querySelector('#curves-body').innerHTML=rows.map(r=>{const assignment=r.assignment||{},suggestion=r.suggestion||{},type=(state.curveWorkbench?.types||[]).find(t=>t.type_key===(assignment.type_key||suggestion.type_key));const hasRange=r.value_min!=null&&r.value_max!=null,distribution=hasRange?`${fmt(r.value_min,4)} – ${fmt(r.value_max,4)}`:'点击读取数值分布';const hint=!r.steps?.length?'缺 STEP':r.steps.length>1?'采样率不一致':r.distributions?.length>2?'检查跨井分布':hasRange?'样本较少':'暂无有效数值样本';return `<tr class="curve-detail-table-row" data-curve-detail="${esc(r.mnemonic)}" data-curve-detail-view="wells"><td><strong>${esc(r.mnemonic)}</strong></td><td>${type?`<span class="tag" style="--tag-color:${esc(type.color)}">${esc(type.name)} · ${assignment.status==='confirmed'?'人工':'建议'}</span>`:'<span class="muted">未分类</span>'}</td><td><button type="button" class="curve-detail-action" data-curve-detail="${esc(r.mnemonic)}" data-curve-detail-view="wells" title="查看具体井名">${fmt(r.well_count)} 口井</button></td><td>${fmt(r.file_count)}</td><td>${esc((r.units||[]).join?.(', ')||r.units||'—')}</td><td>${r.steps?.length?r.steps.map(v=>fmt(v,6)).join(' / '):'—'}</td><td><button type="button" class="curve-detail-action" data-curve-detail="${esc(r.mnemonic)}" data-curve-detail-view="distribution" title="查看数值分布柱状图">${distribution}</button></td><td><span class="${hint==='采样率不一致'?'warning-text':'muted'}">${hint}</span></td></tr>`}).join('')||`<tr><td colspan="8" class="empty-state">暂无曲线</td></tr>`;if(typeof bindCurveCoverageInteractions==='function')bindCurveCoverageInteractions()}
async function loadInterpretations(){state.interpretationWorkbench=await api('/api/interpretation-workbench');state.interpretations=state.interpretationWorkbench.attributes||[];if(typeof renderInterpretationWorkbench==='function')renderInterpretationWorkbench()}
async function loadCore(){state.core=await api('/api/core-calibration');if(typeof renderCoreCalibration==='function')renderCoreCalibration()}
async function loadTimeDepth(query,kind){const q=query??document.querySelector('#time-depth-search')?.value??'',selectedKind=kind??document.querySelector('#time-depth-kind')?.value??'',params=new URLSearchParams();if(q.trim())params.set('q',q.trim());if(selectedKind)params.set('kind',selectedKind);const data=await api('/api/time-depth'+(params.size?`?${params}`:''));state.timeDepth=data.curves||[];state.timeDepthInventory=data;if(typeof renderTimeDepth==='function')renderTimeDepth(data)}
async function loadSeismic(){if(typeof loadSeismicWorkbench==='function')return loadSeismicWorkbench();state.seismic=await api('/api/seismic')}

function productionMatch(row){if(row.match_status==='matched')return '<span class="production-match">已匹配工区井</span>';if(row.match_status==='suggested')return `<span class="production-match suggested" title="候选 ${esc(row.match_suggestion?.well_name||'')} · ${Math.round((row.match_suggestion?.score||0)*100)}%">疑似井名</span>`;return '<span class="production-match unmatched">生产独立证明</span>'}
function productionValue(value,suffix='',digits=2){return value==null?'—':`${fmt(value,digits)}${suffix}`}
function positionOfmHelp(event){const card=document.querySelector('#ofm-help-card');if(!card||card.classList.contains('hidden'))return;const margin=14,width=card.offsetWidth||340,height=card.offsetHeight||220;let left=event.clientX+16,top=event.clientY+14;if(left+width>innerWidth-margin)left=event.clientX-width-16;if(top+height>innerHeight-margin)top=event.clientY-height-14;card.style.left=`${Math.max(margin,left)}px`;card.style.top=`${Math.max(margin,top)}px`}
function showOfmHelp(event,row){const card=document.querySelector('#ofm-help-card'),help=row?.explanation||{};if(!card)return;document.querySelector('#ofm-help-title').textContent=row.table_name;document.querySelector('#ofm-help-purpose').textContent=help.purpose||'OFM 数据表';document.querySelector('#ofm-help-stores').textContent=help.stores||'请打开表查看字段和样例值。';document.querySelector('#ofm-help-note').textContent=help.note||'';document.querySelector('#ofm-help-availability').textContent=help.availability||`${fmt(row.row_count)} 行`;card.classList.remove('hidden');positionOfmHelp(event)}
function hideOfmHelp(){document.querySelector('#ofm-help-card')?.classList.add('hidden')}
