  const run=data.run||{},summary=run.summary||{};source.textContent=`已挂载：${run.corrected_mdb_path} · ${String(run.completed_at||'').replace('T',' ').slice(0,19)}`;metrics.innerHTML=[['处理井',run.well_count],['重建记录',run.record_count],['发生修正井',run.corrected_well_count],['修正指标项',run.corrected_value_count],['推算生产天数',run.inferred_days_count]].map(row=>`<div><b>${fmt(row[1])}</b><span>${row[0]}</span></div>`).join('');stats.innerHTML=(data.field_stats||[]).map(row=>`<button type="button" data-correction-field="${esc(row.field_label)}"><span>${esc(row.field_label)}</span><b>${fmt(row.corrected)} / ${fmt(row.wells)} 口</b><i style="width:${row.wells?row.corrected/row.wells*100:0}%"></i></button>`).join('')||'<div class="empty-state">没有指标审计记录</div>';body.innerHTML=(data.audit||[]).map(row=>`<tr class="${row.changed?'corrected':''}"><td><span class="correction-check ${row.changed?'on':''}">${row.changed?'✓':''}</span></td><td><b>${esc(row.well_name)}</b></td><td>${esc(row.field_label)}</td><td>${row.original_value==null?'—':fmt(row.original_value,3)}</td><td>${row.corrected_value==null?'—':fmt(row.corrected_value,3)}</td><td>${esc(row.unit||'—')}</td><td>${esc(row.reason||'—')}</td></tr>`).join('')||'<tr><td colspan="7" class="empty-state">当前筛选下没有记录</td></tr>';status.textContent=`显示 ${fmt((data.audit||[]).length)} / ${fmt(data.total)} 项 · ✓ 仅表示数值确实发生修正`;document.querySelectorAll('[data-correction-field]').forEach(button=>button.onclick=()=>{const input=document.querySelector('#production-correction-search');input.value=button.dataset.correctionField;loadProductionCorrectionStatus()});
