  document.querySelector('#production-stat-kpis').innerHTML=[['勾选井',count,'口'],['有效生产井',validProduction,'口'],['累计生产天数',days.value,'天'],['覆盖层位',new Set(rows.flatMap(row=>String(row.production_formation||'').split('/').map(value=>value.trim()).filter(Boolean))).size,'个']].map(row=>`<div><span>${row[0]}</span><b>${fmt(row[1])}</b><small>${row[2]}</small></div>`).join('');
