  const yFields=document.querySelector('#production-y-fields');
  if(yFields&&!yFields.querySelector('[value="gas_rate"]'))yFields.insertAdjacentHTML('beforeend','<label><input type="checkbox" value="gas_rate">日产气</label><label><input type="checkbox" value="gas_oil_ratio">汽油比</label>');
